// Craftable equipment, usable supplies and region loot share the same item catalog.
const EXTRA_ITEMS={
 leather:{name:'İşlenmemiş Deri',kind:'material',color:'#b5916a',price:12,description:'Yaratıklardan düşer. Avcı ekipmanları için değerli bir ticaret malzemesi.'},
 fang:{name:'Yırtıcı Dişi',kind:'material',color:'#e1d3ad',price:18,description:'Güçlü orman yaratıklarından düşen sivri diş. Nara satın alır.'},
 coal:{name:'Kara Kömür',kind:'material',color:'#8b949f',price:10,description:'Boran’ın ocağında kullanılan yakıt. Orman ganimeti olarak bulunur.'},
 herb:{name:'Ayçiği Otu',kind:'material',color:'#9bbc88',price:14,description:'Luma bu bitkiyi güçlü can iksirine dönüştürür.'},
 ancientShard:{name:'Kadim Rün Parçası',kind:'material',color:'#b3a4dc',price:55,description:'Harabe bölgesi ve boss’lardan düşer. Savaş iksiri tarifinde kullanılır.'},
 wolfPelt:{name:'Gümüş Post',kind:'material',color:'#bfccd0',price:35,description:'Üst seviye yaratıklardan elde edilen nadir bir post.'},
 greaterPotion:{name:'Büyük Can İksiri',kind:'consumable',color:'#e89cac',price:45,description:'120 can yeniler. Tam candayken harcanmaz.'},
 furyPotion:{name:'Savaş İksiri',kind:'consumable',color:'#efb173',price:65,description:'60 saniye boyunca +10 hasar verir. Yeniden içmek süreyi yeniler; bonus birikmez.'},
 wardPotion:{name:'Taşderi İksiri',kind:'consumable',color:'#94c5d3',price:60,description:'60 saniye boyunca alınan hasarı 4 azaltır. Yeniden içmek süreyi yeniler.'},
 wolfAmulet:{name:'Kurt Dişi Kolyesi',kind:'accessory',color:'#d2c49e',price:160,stats:{damage:4,armor:1},description:'Kuşanıldığında +4 hasar, +1 savunma. İkinci bölgedeki boss’tan düşer.'},
 scholarCharm:{name:'Bilginin Rün Tılsımı',kind:'accessory',color:'#a5bbe0',price:190,stats:{hp:20},description:'Kuşanıldığında +20 azami can verir. Üçüncü bölge boss ganimeti.'},
 ritualCoin:{name:'Kadim Güneş Muskası',kind:'accessory',color:'#dfbf78',price:230,stats:{damage:6,armor:2},description:'Kuşanıldığında +6 hasar, +2 savunma. Harabe Lordu’ndan düşer.'}
};
Object.assign(ITEMS,EXTRA_ITEMS);Object.entries(GEAR).filter(([id])=>!ITEMS[id]).forEach(([id,g])=>ITEMS[id]={...g,kind:'gear',stats:{armor:g.armor||0,damage:g.damage||0},price:Math.floor(g.gold*.4),description:GEAR_SLOTS[g.slot]+' · '+(g.armor?'+'+g.armor+' savunma. ':'')+(g.damage?'+'+g.damage+' hasar. ':'')+'Boran’da üretilebilir.'});
Object.entries(ITEMS).forEach(([id,i])=>{if(id!=='potion')p.inventory[id]=Math.max(0,Math.floor(p.inventory[id]||0));if(i.price)goods[id]={name:i.name,price:i.price,icon:'◆'}});
if(saved?.accessory&&ITEMS[saved.accessory]&&itemCount(saved.accessory))p.accessory=saved.accessory;
if(!p.supplyPackVersion){p.inventory.leather+=2;p.inventory.herb+=3;p.inventory.coal+=3;p.inventory.greaterPotion++;p.supplyPackVersion=1;save()}
if(Array.isArray(saved?.quickSlots))p.quickSlots=saved.quickSlots.slice(0,5).map(id=>itemInfo(id)?id:null);
function itemRarity(id){const i=itemInfo(id),epic=['eclipse','storm','voidCharm','stormCharm','ritualCoin','ancientShard'],rare=['frost','frostCharm','wolfAmulet','scholarCharm','wolfPelt','furyPotion','wardPotion'];const key=id?.replace('sword:','');let rank=epic.includes(key)||id?.startsWith('ember')?3:rare.includes(key)||['mossShield','shadowBoots','rubyEarring'].includes(id)?2:i?.kind==='gear'&&!GEAR[id]?.starter||i?.kind==='sword'&&key!=='tide'?1:0;return[{id:'common',name:'Sıradan',rank:0,color:'#aab3ae'},{id:'uncommon',name:'Nitelikli',rank:1,color:'#99bd89'},{id:'rare',name:'Nadir',rank:2,color:'#92b8df'},{id:'epic',name:'Destansı',rank:3,color:'#c5a1df'}][rank]}
p.buffs=Object.assign({},p.buffs||{});
const beforeSupplyDamage=damage;damage=function(){return beforeSupplyDamage()+(p.buffs.furyUntil>Date.now()?10:0)};
const beforeWardStats=accessoryStats;accessoryStats=function(){const s=beforeWardStats();return{...s,armor:(s.armor||0)+(p.buffs.wardUntil>Date.now()?4:0)}};
const beforeSupplyActivate=activateItem;activateItem=function(id){if(!['greaterPotion','furyPotion','wardPotion'].includes(id))return beforeSupplyActivate(id);if(!itemCount(id))return false;if(id==='greaterPotion'&&p.hp>=p.maxHp){toast('Canın zaten dolu.');return false}p.inventory[id]--;if(id==='greaterPotion')p.hp=Math.min(p.maxHp,p.hp+120);else p.buffs[id==='furyPotion'?'furyUntil':'wardUntil']=Date.now()+60000;save();ui();toast(ITEMS[id].name+' kullanıldı.');return true};
const beforeVariedLoot=loot;loot=function(e){beforeVariedLoot(e);const rank=e.rank||1;p.inventory[rank===1?'herb':rank===2?'leather':rank===3?'fang':'ancientShard']++;if(rand()<.3)p.inventory.coal++;if(rank>=3&&rand()<.2)p.inventory.wolfPelt++;save()};
const beforeVariedBossLoot=awardBossLoot;awardBossLoot=function(e){const id={1:'wolfAmulet',2:'scholarCharm',3:'ritualCoin'}[e.bossIndex];if(id)p.inventory[id]++;p.inventory.greaterPotion++;p.inventory.ancientShard+=e.rank;beforeVariedBossLoot(e)};
const SUPPLY_RECIPES={greaterPotion:{herb:3,jelly:2},furyPotion:{fang:2,ancientShard:1},wardPotion:{coal:3,ore:1}};
function brewSupply(id){const cost=SUPPLY_RECIPES[id];if(!cost||!Object.entries(cost).every(([k,n])=>p.inventory[k]>=n))return false;Object.entries(cost).forEach(([k,n])=>p.inventory[k]-=n);p.inventory[id]++;save();ui();return true}
const beforeExpandedServiceAction=serviceAction;serviceAction=function(action,id){const kind=$('service').dataset.kind;if(action==='brewSupply'||action==='buySupply'){if(p.area!=='hub'||!$('service').open||nearestService()?.id!==kind)return;if(action==='brewSupply'&&kind==='alchemist')brewSupply(id);if(action==='buySupply'&&kind==='merchant'&&['greaterPotion','furyPotion','wardPotion'].includes(id)){const cost={greaterPotion:65,furyPotion:90,wardPotion:85}[id];if(p.gold>=cost){p.gold-=cost;p.inventory[id]++;save();ui()}}renderService();return}beforeExpandedServiceAction(action,id)};
const beforeExpandedServiceRender=renderService;renderService=function(){beforeExpandedServiceRender();const root=$('serviceBody'),kind=$('service').dataset.kind;if(kind==='alchemist'){root.insertAdjacentHTML('beforeend','<h3>Yeni simya tarifleri</h3>'+Object.entries(SUPPLY_RECIPES).map(([id,cost])=>`<div class="shop-row"><span>${ITEMS[id].name}<small>${Object.entries(cost).map(([k,n])=>n+' '+ITEMS[k].name+' ('+p.inventory[k]+')').join(' + ')}</small></span><button data-supply-brew="${id}" ${Object.entries(cost).some(([k,n])=>p.inventory[k]<n)?'disabled':''}>Üret</button></div>`).join(''));root.querySelectorAll('[data-supply-brew]').forEach(b=>b.onclick=()=>serviceAction('brewSupply',b.dataset.supplyBrew))}if(kind==='merchant'&&npcActiveTab==='supply'){root.insertAdjacentHTML('beforeend',Object.entries({greaterPotion:65,furyPotion:90,wardPotion:85}).map(([id,cost])=>`<div class="shop-row"><span>${ITEMS[id].name}<small>${cost} altın · ${ITEMS[id].description}</small></span><button data-supply-buy="${id}" ${p.gold<cost?'disabled':''}>Satın al</button></div>`).join(''));root.querySelectorAll('[data-supply-buy]').forEach(b=>b.onclick=()=>serviceAction('buySupply',b.dataset.supplyBuy))}};
// Readable item illustrations: silhouettes, handles, edges and material shading at 72px.
itemIconHTML=function(id,large=false){const i=itemInfo(id);return i?`<canvas class="illustrated-item ${large?'large':''}" data-illustrated-item="${id}" width="72" height="72" aria-label="${i.name}"></canvas>`:''};
const paintBeforeIllustrated=paintItemIcons;paintItemIcons=function(root){paintBeforeIllustrated(root);root.querySelectorAll('[data-illustrated-item]').forEach(c=>drawInventoryItem(c,c.dataset.illustratedItem))};
